def _host_leak_surface_state(cwd: Path):
    """T-10008 — read `cwd`'s host-leak WATCHED-PATH state for the per-land before/after check, reusing
    the T-0402 canary module's OWN `_leak_lines` predicate (CHARTER §P5 single source — one watched-path
    home). Returns `(watched, fail)`:

      • `watched` = the list of `git status --short` lines the canary classifies as host-leak symptoms
        (a modified/added `graph/index.json`, `decisions/T-99*` debris, an orphan
        `graph/.index.json.*.tmp`) — `[]` when byte-clean, OR
      • `watched` = None when NO guard applies (a CLI-less sandbox temp-repo without the canary file, or
        a `cwd` removed under concurrent cleanup — nothing to leak into).
      • `fail` = a fail-closed reason string (a REAL checkout MISSING the canary, or a `git status` that
        failed on an EXISTING dir); set ⇒ the caller ABORTS the land.

    DELIBERATELY watched-git-status ONLY — NOT the index sha/mtime — to preserve the T-0679 land verdict:
    a byte-changed tracked `graph/index.json` already shows as ` M` in git status (so `_leak_lines`
    catches a real rewrite), while a pure mtime-touch on a byte-clean tree is a transient flake T-0679
    decided must NOT abort the land (`_canary_watched_leaks` is the same watched-only predicate). It runs
    NO test subprocess / NO suite re-run (unlike the retired per-land `_run_host_leak_canary`) — it only
    reads `git status`, so it can never hang (root-fix of the SPEC-0071 land-verify-timeout class)."""
    import importlib.util
    import subprocess
    canary = cwd / "tests" / "test_t0402_host_leak_canary.py"
    if not canary.exists():
        if (cwd / "bin" / "yitc-v2").exists():
            return None, ("host-leak canary MISSING (T-0411 / SPEC-0041 §3): "
                          "tests/test_t0402_host_leak_canary.py absent from a V2 checkout — the standing "
                          "regression guard cannot fire (fail-closed; restore the canary or it never lands)")
        return None, None   # CLI-less sandbox temp-repo (a test harness) — no guard expected here
    try:
        spec = importlib.util.spec_from_file_location("_t0402_canary_state", str(canary))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        status = subprocess.run(["git", "-C", str(cwd), "status", "--short"],
                                capture_output=True, text=True)
        if status.returncode != 0:
            # A REMOVED checkout dir (own/concurrent cleanup) is NOT a failed query — there is no
            # checkout to leak into, so it reads as "no guard" (mirror _canary_watched_leaks / T-9511).
            if not Path(cwd).exists():
                return None, None
            return None, (f"host-leak surface: `git status` failed in {cwd} (rc={status.returncode}, "
                          f"fail-closed): {(status.stderr or status.stdout).strip()[:200]}")
        watched = mod._leak_lines([ln for ln in status.stdout.splitlines() if ln.strip()])
        return watched, None
    except Exception as e:   # loading the predicate must never itself mask the guard → fail closed
        return None, f"host-leak surface read ERROR (T-10008, fail-closed): {type(e).__name__}: {e}"


def _host_leak_land_verdict(cwd: Path, before) -> list:
    """T-10008 — the CHEAP per-land host-leak check that REPLACES the redundant full-suite canary
    re-run. Land ALREADY ran `tests/` on `cwd` via `_run_verify_tests` immediately before, so a
    host-leak that run introduced (a `graph/index.json` rewrite, `decisions/T-99*` debris, an orphan
    `graph/.index.json.*.tmp`) shows up in `cwd`'s watched `git status` afterward. `before` is the
    pre-suite watched-state snapshot (`_host_leak_surface_state`, taken before the `_run_verify_tests`
    call) — a byte-clean tree there is the fail-closed pre-condition; any watched debris after the
    suite is the leak. NO second suite execution ⟹ it can never hang and never leak a child — the
    root-fix of the `land-verify-timeout:test_t0402_host_leak_canary.py` recurrence (SPEC-0066 no
    longer re-runs the suite a second time on the per-land path; the standalone canary + weekly
    `audit canary-backstop` keep the active-run form for surfaces the suite is not otherwise run against).

    Returns `[]` (byte-clean) or `[<reason>]` (folded by `_land_integrate` into `bad` → `_die` →
    `LAND: ABORT`) — the SAME list shape + the SAME watched-only verdict as the retired
    `_run_host_leak_canary`/`_canary_watched_leaks` (T-0679). FAIL-CLOSED on every skip path (a
    snapshot error, or watched debris ALREADY present before the suite) so the guard can never
    silently vanish (CHARTER §Principle 8)."""
    before_watched, before_fail = before if before is not None else (None, None)
    if before_fail:
        return [f"host-leak pre-suite snapshot: {before_fail}"]
    if before_watched is None:
        return []   # no guard applies (CLI-less sandbox / removed cwd)
    if before_watched:
        # watched debris present BEFORE the suite: in land's post-reconcile context a byte-clean tree is
        # expected, so pre-existing debris means the suite/env already leaked (the retired
        # _run_host_leak_canary pre-check failed closed on exactly this — semantics preserved).
        return ["host-leak debris ALREADY present before the suite (suite/env leaked; the canary's "
                f"entry-guard would SKIP — fail-closed): {before_watched}"]
    after_watched, after_fail = _host_leak_surface_state(cwd)
    if after_fail:
        return [f"host-leak post-suite check: {after_fail}"]
    if after_watched is None:
        return []   # cwd removed between snapshots (concurrent cleanup) — nothing to leak into
    if after_watched:
        return ["host-leak canary FAILED (T-0402 / T-10008, snapshot-diff, no suite re-run): "
                f"watched-path debris in the working tree after the suite: {after_watched}"]
    return []


def _capture_reopen_errors_dirt(main_wt: Path, main_dirty: set, *, _run_git_cap, ERRORS_DIR) -> set:
    """The `errors/E-XXXX.yaml` paths in `main_dirty` that are the DETERMINISTIC file-half of a
    capture-time reopen (D-0086 §2 `_reopen_resolved_error`) whose paired `error_reopened` event is in
    main's UNCOMMITTED events.jsonl tail — replayable bookkeeping, NOT foreign source work, so land may
    fold them alongside their already-folded event (T-0615). Evidence-gated: only an errors file whose
    E-id appears in a NEW (working-but-not-HEAD) `error_reopened` event is admitted, so a historical
    reopen cannot launder a foreign edit. FAIL-CLOSED: an E-id whose errors-glob does not resolve to
    EXACTLY ONE file (either canonical `E-NNNN.yaml` / `E-NNNN-*.yaml` shape — same locator as
    `_find_error_yaml`) is NOT admitted (it stays foreign → land blocks). Returns repo-relative
    porcelain paths ⊆ main_dirty (never widens the fold beyond what is actually dirty)."""
    import json
    edir_prefix = ERRORS_DIR.name + "/"          # derive — never a literal (the inert-prefix authority is _INERT_DIR_PREFIXES, T-0631)
    errors_dirty = {p for p in main_dirty if p.startswith(edir_prefix) and p.endswith(".yaml")}
    if not errors_dirty:
        return set()
    mp = main_wt / "events.jsonl"
    if not mp.exists():
        return set()
    # T-11444 / SPEC-0190 rule 4b — the committed set spans the SEGMENT SET at HEAD. This set is what
    # decides which lines are the UNCOMMITTED capture tail; a committed row living in an archive
    # segment would otherwise read as uncommitted and vouch for an errors-file fold it must not vouch
    # for. Pre-rotation this is the single `HEAD:events.jsonl` read, unchanged.
    head_lines = set()
    # T-11805 — ONE git process for the whole fold where that is safe, instead of one fork per
    # segment. Same segments, same fold order, same bytes; `revision_segment_show_argvs` falls back
    # to the per-segment argvs whenever the batch would not be complete, so this can never read less.
    for _argv in journal_mod.revision_segment_show_argvs(
            "HEAD", main_wt, run=lambda a: _run_git_cap(a, main_wt)):
        _h = _run_git_cap(_argv, main_wt)
        if _h.returncode == 0:
            head_lines.update(_h.stdout.splitlines())
    reopened_eids = set()
    for ln in mp.read_text(encoding="utf-8").splitlines():
        if not ln.strip() or ln in head_lines:          # only the uncommitted capture tail vouches
            continue
        try:
            ev = json.loads(ln)
        except Exception:
            continue
        if ev.get("type") == "error_reopened" and isinstance(ev.get("task_id"), str):
            reopened_eids.add(ev["task_id"])
    if not reopened_eids:
        return set()
    edir = main_wt / "errors"
    folded = set()
    for eid in reopened_eids:                            # both canonical shapes; fail-closed on 0/>1
        matches = list(edir.glob(f"{eid}-*.yaml")) + list(edir.glob(f"{eid}.yaml"))
        if len(matches) != 1:
            continue
        rel = matches[0].relative_to(main_wt).as_posix()
        if rel in errors_dirty:
            folded.add(rel)
    return folded


