            bad.extend(_sweep_bad)
            bad.extend(_cguard["bad"])
            if _cguard["mode"]:
                consumer_verify_mode = _cguard["mode"]
                # T-13034: on a consumer land `fail_class` describes the COMBINED candidate verdict
